        "topic": "36氪研究院 | 2026年中国自动驾驶行业发展研究报告",
        "progress": "自动驾驶是人工智能与汽车工业深度融合的战略性技术方向，也是中国智能网联新能源汽车战略性新兴产业中增长最为活跃的领域之一。当前，中国自动驾驶行业正处于从全域道路测试、示范应用迈向规模化商业落地的关键阶段。政策层面，2026年7月，首部针对L3、L4级自动驾驶系统的强制性国家标准（GB44721-2026）正式发布，将于2027年7月1日起实施，为自动驾驶产品确立了统一的安全准入基线；2026年8月，《道路交通安全法》修订草案完成初次审议，首设“自动驾驶汽车的特别规定”专章，填补了自动驾驶法律责任的顶层空白。技术层面，",
