        "progress": "韩国10月出口维持强劲增长，人工智能热潮持续拉动这个依赖贸易的经济体。韩国产业部周日公布的数据显示，经工作日差异调整后，出口同比大增76.1%，出口额达1153亿美元，上月出口曾创下1211亿美元的历史新高。未经调整口径下，出口同比上涨93.7%，进口增长36%，贸易顺差425亿美元；9月出口增幅修正后为83.7%。出口持续强劲，为韩国央行本月加息提供支撑。半导体仍是拉动增长的主力，芯片出口同比暴涨259%，至564亿美元；计算机出口增长497%，石化产品、汽车出口分别上涨80%和18%。（新浪财经）",
