        "progress": "作者｜黄楠 采访 | 黄楠 邱晓芬 编辑｜袁斯来 今年春天，FA何紫洋办公室里，地区招商团队成了常客。 她就职于一家服务硬科技赛道的财务顾问机构，日常工作就是帮具身初创公司对接投资机构。最忙的一天，她接待了天津、深圳、成都、厦门四波政府团队，其中大多是区级招商中心人员，也有地级市的负责人。 有些“跟随型城市”的招商团队直接告诉她：“我们也找不到什么方向，政策说啥我们就弄啥。”其中不乏一些地方团队的盘算显得不切实际，一个人口只有几十万的县级市，有深厚的制造业资源。对方能说出本地一整套产业图谱：厂房现成、配套齐全，上下",
